import unittest

# Injected by the Runtime self-check harness. Do not import these names.
# call_candidate(target_path, function, args=[...]) -> JSON value
# CandidateCallError -> raised when the candidate call fails
# check_api_boundary(target_path, rule=..., contract_path=..., requirement_quote=..., args=[...])

README = "README.md"

# Every transform API in the workspace is covered by the README rule that
# unknown object fields also reject non-finite values, and that a non-object
# top-level payload is invalid.
API_BOUNDARY_REQUIREMENTS = [
    {
        "target_path": "domains/calendar/transform.py",
        "function": "transform",
        "rules": {
            "nonfinite_unknown_field": {
                "applicable": True,
                "contract_path": README,
                "requirement_quote": "未知额外字段可忽略，但其中非有限JSON仍非法",
            },
            "invalid_payload_type": {
                "applicable": True,
                "contract_path": README,
                "requirement_quote": "仅对象/数组顶层合法；非法JSON、其他顶层类型和任意嵌套NaN/Infinity抛ValueError",
            },
        },
    },
